head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gProcType;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gComAbbrv;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

